    ds=[.36,0,.42,0,.4,0,.126]
    al=[-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,-np.pi/2,np.pi/2,0]
    for t,d,a in zip(q,ds,al):
        ct,st,ca,sa=np.cos(t),np.sin(t),np.cos(a),np.sin(a)
        T=T@np.array([[ct,-st*ca,st*sa,0],[st,ct*ca,-ct*sa,0],[0,sa,ca,d],[0,0,0,1]])
    return T

def icp(a,b,init=None,steps=40,thresh=.025):
    T=np.eye(4) if init is None else init.copy();tree=cKDTree(b)
    for i in range(steps):
        at=a@T[:3,:3].T+T[:3,3];d,j=tree.query(at);mask=d<thresh
        aa=at[mask];bb=b[j[mask]]
        if len(aa)<15:break
        ma=aa.mean(0);mb=bb.mean(0);u,s,v=np.linalg.svd((aa-ma).T@(bb-mb));R=v.T@u.T
        if np.linalg.det(R)<0:v[-1]*=-1;R=v.T@u.T
        delta=np.eye(4);delta[:3,:3]=R;delta[:3,3]=mb-R@ma;T=delta@T
        if np.linalg.norm(delta[:3,3])+np.linalg.norm(R-np.eye(3))<1e-6:break
    return T, np.mean(d[mask]),mask.sum()
